<script setup lang="ts">import {ref,computed,reactive} from 'vue';import PageTitle from '../components/common/PageTitle.vue';import Empty from '../components/common/Empty.vue';import Status from '../components/common/Status.vue';import Table from '../components/common/Table.vue';import InferenceSummary from '../components/InferenceSummary.vue';import StateBands from '../components/StateBands.vue';import PosteriorGrid from '../components/PosteriorGrid.vue';import ProfileMatrix from '../components/ProfileMatrix.vue';import {researchApi} from '../api/research';import {fmt} from '../utils/format';const p=defineProps<{runs:any[];selectedId:number;user:any;reloadResearch:()=>Promise<void>}>(),emit=defineEmits(['open']),traceId=ref(0),retrying=reactive<Record<number,boolean>>({});const run=computed(()=>p.runs.find(r=>r.id===p.selectedId)||p.runs[0]);const trace=computed(()=>run.value?.result?.traces.find((t:any)=>t.id===traceId.value)||run.value?.result?.traces[0]);const failedRounds=computed(()=>((run.value?.attempt_history||[]) as any[]).filter(h=>h.phase==='failed'));function open(e:Event){emit('open',p.runs.find(r=>r.id===Number((e.target as HTMLSelectElement).value)))}async function retry(){const r=run.value;if(!r||retrying[r.id])return;retrying[r.id]=true;try{await researchApi.retryRun(r.id);await p.reloadResearch()}catch(e){alert((e as Error).message)}finally{retrying[r.id]=false}}</script><template><PageTitle index="04" title="单点分布，与整段联合路径分开读。" description="前向后向得到边际后验；Viterbi得到固定模型下整段联合MAP。"/><label>结果运行<select :value="run?.id||0" @change="open"><option v-for="r in runs" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><p v-if="run"><Status :value="run.status"/>　第 {{run.attempt_no||1}} 轮<span v-if="run.error">　{{run.error}}</span></p><template v-if="run?.result"><InferenceSummary :result="run.result"/><label>观测轨迹<select :value="trace?.id||0" @change="traceId=Number(($event.target as HTMLSelectElement).value)"><option v-for="t in run.result.traces" :key="t.id" :value="t.id">{{t.reference}}</option></select></label><div class="trace-metrics"><span>序列logL <strong>{{fmt(trace.log_likelihood,8)}}</strong></span><span>联合MAP logP <strong>{{fmt(trace.viterbi_log_joint,8)}}</strong></span><span>{{trace.linear_likelihood_underflows?'线性概率下溢，logL仍有限':'线性概率 '+trace.likelihood_if_representable.toExponential(6)}}</span></div><StateBands :trace="trace" :states="run.result.states"/><PosteriorGrid :trace="trace" :states="run.result.states"/><section class="section"><h2>所选轨迹逐条核对</h2><Table :headers="['轨迹','步数','序列logL','联合MAP logP','单点拼接合法性']"><tr v-for="t in run.result.traces" :key="t.id"><td>{{t.reference}}</td><td>{{t.tokens.length}}</td><td>{{fmt(t.log_likelihood,7)}}</td><td>{{fmt(t.viterbi_log_joint,7)}}</td><td>{{t.marginal_path_is_legal?'合法（仍非联合定义）':'非法零概率路径'}}</td></tr></Table></section><ProfileMatrix :profile="run.result.profile"/><details class="provenance"><summary>冻结指纹与所选轨迹完整log数组</summary><p class="fingerprint">{{run.result.fingerprint}}</p><p>{{trace.tie_rule}}</p><p>{{trace.null_log_meaning}}</p><Table :headers="['步','观测','log forward','log backward']"><tr v-for="(token,i) in trace.tokens" :key="i"><td>{{Number(i)+1}}</td><td>{{token}}</td><td>{{JSON.stringify(trace.log_forward[i])}}</td><td>{{JSON.stringify(trace.log_backward[i])}}</td></tr></Table></details><div class="boundary-note"><strong>隐态由固定模型定义，不是故障事实。</strong><p>同一观测在不同参数版本下可有不同解释；这里没有EM训练、在线告警或真实设备诊断保证。</p></div><a href="#notes" class="text-action">建立工况核对说明 →</a></template><template v-else-if="run?.status==='failed'"><Empty :title="'本次观测在模型下不可行或推断失败（第'+(run.attempt_no||1)+'轮）'" :help="run.error||'核对观测字母表与模型后，可在原地重试，仍使用首次排队冻结的模型与观测快照。'"/><div class="retry-panel"><button v-if="user.role!=='viewer'" class="primary" :disabled="retrying[run.id]" @click="retry">{{retrying[run.id]?'重新排队中…':'原地重试（沿用首次冻结快照）↻'}}</button><p v-else class="copper">失败运行可由分析员或负责人在页面原地重试。</p><details v-if="run.attempt_history?.length" open><summary>每轮错误与重试记录</summary><ul class="attempt-log"><li v-for="h in run.attempt_history" :key="h.attempt+'-'+h.phase+'-'+h.at"><small>{{h.at}} · 第{{h.attempt}}轮 · {{h.phase}}<template v-if="h.retried_by"> · {{h.retried_by}}</template><span v-if="h.error" class="copper">：{{h.error}}</span></small></li></ul></details></div></template><Empty v-else title="等待真实worker推断" help="核对观测字母表与模型后，选择1–30条轨迹排队。"/></template>
